function resolveVariant(input) {
  const variantNames = Object.keys(input.variants);
  if (variantNames.length === 0) {
    throw new TypeError("resolveVariant requires at least one prompt variant");
  }
  if (isPlannerAgent2(input.agentName) && variantNames.includes("planner")) {
    return "planner";
  }
  if (input.modelID !== undefined) {
    for (const variantName of variantNames) {
      if (matchesModelVariant(variantName, input.modelID))
        return variantName;
    }
  }
  if (variantNames.includes("default"))
    return "default";
  return variantNames[0];
}
function isPlannerAgent2(agentName) {
  return agentName !== undefined && PLANNER_AGENT_NAMES.has(agentName.toLowerCase());
}
function matchesModelVariant(variantName, modelID) {
  const matcher = MODEL_MATCHERS[variantName];
  return matcher?.(modelID) ?? false;
}
